BEGIN;

CREATE TYPE "Currency" AS ENUM ('PLN');

CREATE TABLE "Wallet" (
    "id" UUID NOT NULL,
    "userId" UUID NOT NULL,
    "name" TEXT NOT NULL DEFAULT 'Mój portfel',
    "currency" "Currency" NOT NULL DEFAULT 'PLN',
    "openingBalance" DECIMAL(14,2) NOT NULL DEFAULT 0,

    CONSTRAINT "Wallet_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "Wallet_userId_key" ON "Wallet"("userId");

ALTER TABLE "Wallet" ADD CONSTRAINT "Wallet_userId_fkey"
    FOREIGN KEY ("userId") REFERENCES "User"("id")
    ON DELETE CASCADE ON UPDATE CASCADE;

-- uuid() is generated by Prisma, so SQL backfill supplies its own UUIDs.
INSERT INTO "Wallet" ("id", "userId")
SELECT gen_random_uuid(), "id" FROM "User";

COMMIT;
